pub struct Order { id: OrderId, customer: CustomerId, lines: Vec<Line>, status: Status }

impl Order {
    pub fn try_open(customer: CustomerId, lines: Vec<Line>) -> Result<Self, OrderError> {
        if lines.is_empty() {
            return Err(OrderError::Empty);
        }
        Ok(Self { id: OrderId::new(), customer, lines, status: Status::Draft })
    }
}

